const MAX_WALK_PASSES = 8;

/**
 * 맨 아래에서 위로 걸으며 남은 글을 처리한다. 끌올하거나 창을 닫고 돌아오면 목록이 맨 위로 되돌아가
 * 위로만 걷는 한 판은 아래·가운데 글에 닿지 못한 채 끝난다(2026-11-07 가격만 12건·끌올 1건 놓침).
 * 한 판에서 하나라도 처리했는데 남은 글이 있으면 맨 아래부터 다시 걷는다. 진전이 없으면 멈춘다.
 */
function walkUp(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	pending: Map<string, BatchItem>,
	tally: Tally,
	book?: BumpBook,
) {
	for (let pass = 0; pass < MAX_WALK_PASSES && pending.size > 0; pass++) {
		const before = pending.size;
		walkPass(serial, exec, ops, pending, tally, book);
		if (tally.stop || pending.size === before) break;
	}
	for (const title of pending.keys()) {
		tally.skipped += 1;
		noteSkip(title, "판매중 목록에서 제목을 못 찾음");
	}
}

