describe("시작 가격 직접 고치기", () => {
	const day = "2026-11-01";

	test("시작 가격을 직접 주면 일정은 그대로 두고 그 값을 쓴다", () => {
		const { store } = open();
		const row = store.listings()[0];
		store.saveListing(row.id, { target: row.price - 5_000, until: "2026-12-31" }, day);
		store.saveListing(row.id, { startPrice: row.price + 20_000 }, "2026-11-05");
		expect(store.listings()[0]).toMatchObject({ startPrice: row.price + 20_000, startDate: day });
	});

	test("일정을 바꾸며 시작 가격도 주면 그 값과 오늘이 시작이다", () => {
		const { store } = open();
		const row = store.listings()[0];
		store.saveListing(row.id, { target: row.price - 5_000, until: "2026-12-31" }, day);
		store.saveListing(row.id, { until: "2026-12-30", startPrice: row.price + 10_000 }, "2026-11-05");
		expect(store.listings()[0]).toMatchObject({ startPrice: row.price + 10_000, startDate: "2026-11-05" });
	});

	test("null 을 주면 지금 가격에서 다시 시작한다", () => {
		const { store } = open();
		const row = store.listings()[0];
		store.saveListing(row.id, { target: row.price - 5_000, until: "2026-12-31" }, day);
		store.saveListing(row.id, { startPrice: row.price + 20_000 }, day);
		store.saveListing(row.id, { startPrice: null }, "2026-11-05");
		expect(store.listings()[0]).toMatchObject({ startPrice: row.price, startDate: "2026-11-05" });
	});

	test("일정이 없으면 시작 가격을 받지 않는다", () => {
		const { store } = open();
		const row = store.listings().find((item) => item.target === null);
		if (!row) throw new Error("시드에 일정 없는 글이 없어요");
		store.saveListing(row.id, { startPrice: 99_000 }, day);
		expect(store.listings().find((item) => item.id === row.id)).toMatchObject({ startPrice: null, startDate: null });
	});
});

describe("인하 때의 관심 기록", () => {
	const card = {
		title: "3단 책장",
		price: 10_000,
		area: "방배4동",
		postedAgoDays: 3,
		bumpAgoDays: 0,
		bumpAgoMinutes: 725,
		bumpCount: 2,
		views: 61,
		chats: 1,
		hearts: 4,
	};

	test("처음에는 기준이 없다", () => {
		const { store } = open();
		expect(store.listings().every((row) => row.cutHearts == null)).toBe(true);
	});

	test("전보다 가격이 내려간 글은 그 순간의 관심을 기준으로 남긴다", () => {
		const { store } = open();
		store.replaceFromPhone([{ ...card, price: 9_000, hearts: 4 }]);
		expect(store.listings()[0]).toMatchObject({ price: 9_000, cutHearts: 4 });
	});

	test("가격이 그대로면 기준을 이어 받고, 관심만 늘어도 기준은 바뀌지 않는다", () => {
		const { store } = open();
		store.replaceFromPhone([{ ...card, price: 9_000, hearts: 4 }]);
		store.replaceFromPhone([{ ...card, price: 9_000, hearts: 7 }]);
		expect(store.listings()[0]).toMatchObject({ hearts: 7, cutHearts: 4 });
	});

	test("다시 내리면 기준이 새 관심으로 바뀐다", () => {
		const { store } = open();
		store.replaceFromPhone([{ ...card, price: 9_000, hearts: 4 }]);
		store.replaceFromPhone([{ ...card, price: 8_500, hearts: 6 }]);
		expect(store.listings()[0]).toMatchObject({ price: 8_500, cutHearts: 6 });
	});

	test("가격이 올랐으면 기준을 바꾸지 않는다", () => {
		const { store } = open();
		store.replaceFromPhone([{ ...card, price: 9_000, hearts: 4 }]);
		store.replaceFromPhone([{ ...card, price: 9_500, hearts: 5 }]);
		expect(store.listings()[0]).toMatchObject({ price: 9_500, cutHearts: 4 });
	});
});

describe("시작가 채우기", () => {
	test("시작가 없이 저장된 일정은 열린 날의 가격에서 시작한다", () => {
		const { store } = open();
		const scheduled = store.listings().filter((row) => row.target !== null && row.until !== null);
		expect(scheduled.length).toBeGreaterThan(0);
		for (const row of scheduled) {
			expect(row.startPrice).toBe(row.price);
			expect(row.startDate).not.toBeNull();
		}
	});
});

