function isStatus(node: Node): boolean {
	return STATUS.has(node.text) && node.desc === "";
}

export function parseSalesDump(xml: string): DumpResult {
	if (!xml.includes("판매관리") && !xml.includes("판매중")) {
		return { ok: false, error: { kind: "not-sales-screen", message: "판매관리 화면이 아니에요" } };
	}
	const nodes = [...xml.matchAll(/<node\b([^>]*)>/g)].map((match) => attrs(match[1]));
	const tab = nodes.find((node) => node.desc.startsWith("판매중 "));
	const tabCount = tab ? Number(tab.desc.replace(/[^\d]/g, "")) || null : null;

	const cards: DumpCard[] = [];
	let i = 0;
	while (i < nodes.length) {
		const node = nodes[i];
		if (isStatus(node)) {
			const built = readCard(nodes, i + 1, node.text === "예약중");
			if (built.error) return { ok: false, error: built.error };
			if (built.card) cards.push(built.card);
			i = built.next;
			continue;
		}
		i += 1;
	}

	if (cards.length === 0) {
		return { ok: false, error: { kind: "no-sales", message: "판매중 카드를 못 읽었어요" } };
	}
	return { ok: true, cards: uniqueByTitle(cards), tabCount };
}

