/** 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다. */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	const minutes = card.bumpAgoMinutes ?? (card.bumpAgoDays === null ? null : Math.round(card.bumpAgoDays * 1_440));
	if (minutes === null || !Number.isFinite(minutes)) return prior;
	return new Date(now - minutes * 60_000).toISOString();
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값이 있으면 그 값보다 늦은 추정으로만 덮는다.
 * 관측을 추정으로 앞당기지는 않는다.
 */
function ingestedNextBumpAt(input: {
	priorNext: string | null;
	bumpedAt: string | null;
	bumpCount: number | null;
}): string | null {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	return laterOf(input.priorNext, estimate);
}

edits.newText:
/** 폰 문구 `끌올 N일·시간·분 전`을 지금 기준 ISO로. 문구가 없으면 이전 시각을 이어 쓴다. 하루 단위만 있으면 그 날에 맞는 아는 시각을 유지한다. */
function ingestedBumpedAt(card: DumpCard, prior: string | null, now: number): string | null {
	if (card.bumpAgoMinutes != null && Number.isFinite(card.bumpAgoMinutes)) {
		return new Date(now - card.bumpAgoMinutes * 60_000).toISOString();
	}
	if (card.bumpAgoDays == null || !Number.isFinite(card.bumpAgoDays)) return prior;
	if (prior && sameDayAgo(prior, now, card.bumpAgoDays)) return prior;
	return new Date(now - Math.round(card.bumpAgoDays * 1_440) * 60_000).toISOString();
}

/** `N일 전`은 날 단위라, 아는 시각의 나이(일)가 같으면 문구와 맞는다. */
function sameDayAgo(prior: string, now: number, days: number): boolean {
	const at = Date.parse(prior);
	if (!Number.isFinite(at) || at > now) return false;
	return Math.floor((now - at) / 86_400_000) === days;
}

/**
 * 다음 끌올 가능 시각. 폰이 보여 준 관측값보다 늦은 추정만 그 값을 덮는다.
 * 추정표로 채운 지난 값은 관측이 아니라서, 새 추정이 더 일어도 지키지 않는다.
 */
function ingestedNextBumpAt(input: {
	priorNext: string | null;
	priorBumpedAt: string | null;
	priorBumpCount: number | null;
	bumpedAt: string | null;
	bumpCount: number | null;
}): string | null {
	const count = input.bumpCount;
	const estimate =
		input.bumpedAt === null || count === null || count < 1 ? null : estimateNextBumpAt(input.bumpedAt, count);
	if (!observedNext(input.priorNext, input.priorBumpedAt, input.priorBumpCount)) return estimate;
	return laterOf(input.priorNext, estimate);
}

/** 폰이 알려 준 다음 시각만 관측이다. 추정표와 같은 값은 추정이라 새 추정으로 바꾼다. */
function observedNext(next: string | null, bumpedAt: string | null, bumpCount: number | null): boolean {
	if (next === null) return false;
	if (bumpedAt === null || bumpCount === null || bumpCount < 1) return true;
	return estimateNextBumpAt(bumpedAt, bumpCount) !== next;
}

