/** 목록 끝까지 민다. 노출이 최근인 글이 위, 오래된 글이 아래다. 앞에 본 끝 글이 플링 한 번에 보이면 확인 스와이프는 더하지 않는다. */
function scrollToEdge(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	edge: "top" | "bottom",
	known = "",
): string {
	let prev = "";
	let stuck = 0;
	let settled = known;
	for (let page = 0; page < 24; page++) {
		if (stopRequested()) return settled;
		const parsed = parseSalesDump(page === 0 ? dumpXml(serial, exec) : settledXml(serial, exec));
		const cards = parsed.ok ? parsed.cards : [];
		const head = (edge === "top" ? cards[0]?.title : cards[cards.length - 1]?.title) ?? "";
		if (head) settled = head;
		if (page > 0 && known !== "" && head !== "" && head === known) return head;
		if (page > 0 && head !== "" && head === prev) {
			stuck += 1;
